def localize_label(text, language_code=None):
    """Return ``text`` in the given language, falling back to the English key
    for English, unknown languages, and untranslated labels."""
    if not text or not language_code or language_code == "en":
        return text
    return LABEL_TEXT.get(text, {}).get(language_code) or text
